declaration:
FUNCTION_BLOCK FB

VAR_INPUT
    startBtn : BOOL;
    resetBtn : BOOL;
    doneSensor : BOOL;
    targetVol : REAL;
    flowVol : REAL;
END_VAR
VAR_OUTPUT
    valveOpen : BOOL;
    fillsToday : INT;
END_VAR
VAR
    startPrev : BOOL;
    resetPrev : BOOL;
    startEdge : BOOL;
    resetEdge : BOOL;
    accumulated : REAL;
    filling : BOOL;
    waitAck : BOOL;
END_VAR

implementation:
startEdge := startBtn AND NOT startPrev;
startPrev := startBtn;
resetEdge := resetBtn AND NOT resetPrev;
resetPrev := resetBtn;


IF resetEdge THEN
    fillsToday := 0;
    valveOpen := FALSE;
    filling := FALSE;
    waitAck := FALSE;
    accumulated := 0.0;
ELSE


    IF startEdge AND waitAck THEN
        waitAck := FALSE;
    END_IF
    IF startEdge AND NOT filling THEN
        filling := TRUE;
        valveOpen := TRUE;
        accumulated := 0.0;
    END_IF

    IF filling THEN
        accumulated := accumulated + flowVol;

        IF accumulated >= targetVol THEN
            valveOpen := FALSE;
            filling := FALSE;
            waitAck := TRUE;
        END_IF
    END_IF


    IF waitAck AND doneSensor THEN
        IF fillsToday < 32767 THEN
            fillsToday := fillsToday + 1;
        END_IF;
        waitAck := FALSE;
    END_IF
END_IF
